package app.swarsetu.stt.sravaani

import java.io.InputStream
import java.nio.ByteBuffer
import java.nio.ByteOrder
import kotlin.math.PI
import kotlin.math.cos
import kotlin.math.sin

/**
 * The fixed SraVaani 0.5 featurization tables, loaded from `assets/sravaani/tables.bin`.
 *
 * The binary is generated by `scripts/sravaani/gen_android_assets.py` directly from the
 * official `preproc.pt` shipped with [ARTPARK-IISc/SraVaani-0.5-live](https://huggingface.co/ARTPARK-IISc/SraVaani-0.5-live)
 * (pinned revision `29a15303`), so the Kotlin featurizer consumes the exact same analysis
 * window and mel filterbank as the official wrapper — not a re-derivation.
 *
 * Layout (little-endian): magic "SRVT" (u32) | version (u32) | n_fft (u32) | win_length (u32) |
 * hop (u32) | mel_bins (u32) | fb_bins (u32) | window[win_length] f32 | mel_fb[mel_bins*fb_bins] f32.
 *
 * Also precomputes the fused DFT basis (the same Conv1D kernel the ONNX featurizer export uses):
 * `cosTab[k][j] = window[j] * cos(2*pi*j*k/n_fft)`, `sinTab[k][j] = window[j] * sin(...)`.
 * Because the model consumes only `|X[k]|^2`, summing over the 400-sample window (not the full
 * 512-point frame) is exact: the dropped phase factor `e^{-2*pi*i*k*frameStart/512}` has unit
 * magnitude. This was verified numerically by the P3 export equivalence gate (max rel 2.6e-05).
 */
class SravaaniTables private constructor(
    val nFft: Int,
    val winLength: Int,
    val hopLength: Int,
    val melBins: Int,
    val fbBins: Int,
    /** Analysis window, [winLength] samples (from official preproc.pt). */
    val window: FloatArray,
    /** Mel filterbank, row-major [melBins][fbBins] (from official preproc.pt). */
    val melFb: FloatArray,
    /** Fused window+DFT cos basis, row-major [fbBins][winLength]. */
    val cosTab: FloatArray,
    /** Fused window+DFT sin basis, row-major [fbBins][winLength]. */
    val sinTab: FloatArray,
) {
    companion object {
        /** "SRVT" as a little-endian u32 (0.5 format). */
        const val MAGIC_05: Int = 0x54565253
        /** "SRV1" as a little-endian u32 (1.0 format). */
        const val MAGIC_10: Int = 0x53525631
        const val MAGIC: Int = MAGIC_10
        const val VERSION: Int = 1

        fun read(input: InputStream): SravaaniTables {
            val buf = ByteBuffer.wrap(input.readBytes()).order(ByteOrder.LITTLE_ENDIAN)
            val magic = buf.int
            val nFft: Int
            val win: Int
            val hop: Int
            val melBins: Int
            val fbBins: Int

            when (magic) {
                MAGIC_10 -> {
                    nFft = buf.int
                    hop = buf.int
                    win = buf.int
                    melBins = buf.int
                    fbBins = nFft / 2 + 1
                    // 4 float scalars: preemph, guard, pad_val, constant
                    val preemph = buf.float
                    val guard = buf.float
                    val padVal = buf.float
                    val constant = buf.float
                }
                MAGIC_05 -> {
                    val ver = buf.int
                    require(ver == VERSION) { "tables.bin: unsupported 0.5 version $ver" }
                    nFft = buf.int
                    win = buf.int
                    hop = buf.int
                    melBins = buf.int
                    fbBins = buf.int
                }
                else -> {
                    throw IllegalArgumentException("tables.bin: bad magic 0x${Integer.toHexString(magic).uppercase()}")
                }
            }

            require(nFft in 2..(1 shl 20) && win in 1..nFft && hop in 1..nFft) {
                "tables.bin: implausible geometry ($nFft, $win, $hop)"
            }
            require(melBins in 1..4096 && fbBins == nFft / 2 + 1) {
                "tables.bin: implausible filterbank ($melBins x $fbBins)"
            }

            val window = FloatArray(win) { buf.float }
            val melFb = FloatArray(melBins * fbBins) { buf.float }
            require(buf.remaining() == 0) { "tables.bin: trailing bytes (${buf.remaining()})" }

            // Fused DFT basis. Doubles during construction, f32 at rest —
            // matches how the export script built the equivalent Conv1D kernel.
            val cosTab = FloatArray(fbBins * win)
            val sinTab = FloatArray(fbBins * win)
            for (k in 0 until fbBins) {
                val angleStep = 2.0 * PI * k / nFft
                val cRow = k * win
                for (j in 0 until win) {
                    val angle = angleStep * j
                    val w = window[j].toDouble()
                    cosTab[cRow + j] = (w * cos(angle)).toFloat()
                    sinTab[cRow + j] = (w * sin(angle)).toFloat()
                }
            }
            return SravaaniTables(nFft, win, hop, melBins, fbBins, window, melFb, cosTab, sinTab)
        }
    }
}
